import { NxButtonComponent } from '@allianz/ng-aquila/button';
import { AsyncPipe } from '@angular/common';
import { HttpClient } from '@angular/common/http';
import {
  ChangeDetectorRef,
  Component,
  ElementRef,
  ViewChild,
  ViewEncapsulation,
} from '@angular/core';
import { AgGridAngular, AgGridModule } from 'ag-grid-angular';
import {
  AllCommunityModule,
  CellClickedEvent,
  ClientSideRowModelModule,
  ColDef,
  ColGroupDef,
  GridApi,
  GridReadyEvent,
  ModuleRegistry,
  RowSelectionOptions,
} from 'ag-grid-community';
import { Observable } from 'rxjs';

ModuleRegistry.registerModules([ClientSideRowModelModule, AllCommunityModule]);
/**
 * @title Ag-grid example
 */
@Component({
  selector: 'ag-grid-example',
  templateUrl: './ag-grid-example.html',
  styleUrls: ['./ag-grid-example.css'],
  imports: [NxButtonComponent, AgGridModule, AsyncPipe],
  encapsulation: ViewEncapsulation.ShadowDom,
})
export class AgGridExampleComponent {
  rowSelection: RowSelectionOptions = {
    mode: 'multiRow',
    headerCheckbox: true,
    checkboxes: true,
  };
  floatingFilter = true;
  columnsNoGroup: ColDef[] = [
    {
      colId: 'make',
      field: 'make',
      filter: 'agTextColumnFilter',
      resizable: true,
    },
    {
      field: 'model',
      filter: 'agTextColumnFilter',
      resizable: true,
    },
    {
      field: 'price',
      filter: 'agTextColumnFilter',
      resizable: true,
    },
  ];

  showGroup = true;
  // Each Column Definition results in one Column.
  columnsWithGroup: (ColDef | ColGroupDef)[] = [
    {
      colId: 'make',
      field: 'make',
      filter: 'agTextColumnFilter',
      resizable: true,
    },
    {
      headerName: 'Group 1',
      resizable: true,
      initialHide: true,
      showRowGroup: false,
      children: [
        {
          field: 'model',
          filter: 'agTextColumnFilter',
          resizable: true,
        },
        {
          field: 'price',
          filter: 'agTextColumnFilter',
          resizable: true,
        },
      ],
    },
    {
      field: 'model',
      filter: 'agTextColumnFilter',
      resizable: true,
    },
    {
      field: 'price',
      filter: 'agTextColumnFilter',
      resizable: true,
    },
  ];

  // DefaultColDef sets props common to all Columns
  defaultColDef: ColDef = {
    editable: true,
    sortable: true,
    filter: true,
    resizable: true,
    floatingFilter: this.floatingFilter,
  };

  // Data that gets displayed in the grid
  rowData$!: Observable<any[]>;

  @ViewChild(AgGridAngular, { read: ElementRef }) agGridElement!: ElementRef;
  // For accessing the Grid's API
  @ViewChild(AgGridAngular) agGrid!: AgGridAngular;
  private gridApi!: GridApi;

  constructor(
    private readonly http: HttpClient,
    private readonly _cdr: ChangeDetectorRef,
  ) {}

  // Example load data from server
  onGridReady(params: GridReadyEvent) {
    this.gridApi = params.api;
    this.rowData$ = this.http.get<any[]>(
      'https://www.ag-grid.com/example-assets/row-data.json',
    );
    this.gridApi.sizeColumnsToFit();
  }

  // Example of consuming Grid Event
  onCellClicked(e: CellClickedEvent): void {
    console.log('cellClicked', e);
  }

  // Example using Grid's API
  clearSelection(): void {
    this.agGrid.api.deselectAll();
  }

  dense = false;
  toggleDense() {
    this.dense = !this.dense;
  }
  zebra = false;
  toggleZebra() {
    this.zebra = !this.zebra;
  }

  toggleCheckboxSelection() {
    const columnDefs = this.gridApi.getColumnDefs();
    if (!columnDefs) {
      return;
    }
    const currentSelection = this.gridApi.getGridOption(
      'rowSelection',
    ) as RowSelectionOptions;
    const currentCheckboxes = currentSelection.checkboxes ?? false;
    this.gridApi.setGridOption('rowSelection', {
      ...this.rowSelection,
      mode: 'multiRow',
      headerCheckbox: !currentCheckboxes,
      checkboxes: !currentCheckboxes,
    });
    this.gridApi.setGridOption('columnDefs', []);
    this.gridApi.setGridOption('columnDefs', columnDefs);
    this.gridApi.sizeColumnsToFit();
  }

  toggleGroup() {
    this.showGroup = !this.showGroup;
    this.gridApi.setGridOption(
      'columnDefs',
      this.showGroup ? this.columnsWithGroup : this.columnsNoGroup,
    );
    this.gridApi.sizeColumnsToFit();
  }

  toggleFloatingFilter() {
    this.floatingFilter = !this.floatingFilter;
    this.defaultColDef = {
      ...this.defaultColDef,
      floatingFilter: this.floatingFilter,
    };
  }
}

