import { NxFormfieldControl } from '@allianz/ng-aquila/formfield';
import { IdGenerationService } from '@allianz/ng-aquila/utils';
import { FocusMonitor } from '@angular/cdk/a11y';
import { BooleanInput, coerceBooleanProperty } from '@angular/cdk/coercion';
import {
  AfterViewInit,
  Component,
  ElementRef,
  inject,
  Input,
  OnDestroy,
  Optional,
  Self,
} from '@angular/core';
import {
  ControlValueAccessor,
  FormBuilder,
  FormGroup,
  FormsModule,
  NgControl,
  ReactiveFormsModule,
  Validators,
} from '@angular/forms';
import { Subject } from 'rxjs';
import { takeUntil } from 'rxjs/operators';

/**
 * @title Implementing Custom Formfield Control example
 */

/** Data structure for holding telephone number. */
export class MyTel {
  constructor(
    readonly area: string,
    readonly exchange: string,
    readonly subscriber: string,
  ) {}
}

/** Custom `NxFormFieldControl` for telephone number input. */
@Component({
  selector: 'formfield-custom-tel-input-example',
  templateUrl: 'formfield-custom-tel-input-example.html',
  styleUrls: ['formfield-custom-tel-input-example.css'],
  providers: [
    {
      provide: NxFormfieldControl,
      useExisting: FormfieldCustomTelInputExampleComponent,
    },
  ],
  host: {
    '[class.example-floating]': 'shouldLabelFloat',
    '[id]': 'id',
    '[attr.aria-describedby]': 'describedBy',
  },
  imports: [FormsModule, ReactiveFormsModule],
})
export class FormfieldCustomTelInputExampleComponent
  implements
    ControlValueAccessor,
    NxFormfieldControl<MyTel>,
    OnDestroy,
    AfterViewInit
{
  readonly parts: FormGroup;
  readonly!: boolean;
  readonly stateChanges = new Subject<void>();
  focused = false;
  errorState = false;
  controlType = 'example-tel-input';
  id = inject(IdGenerationService).nextId('example-tel-input');
  describedBy = '';

  get empty() {
    const {
      value: { area, exchange, subscriber },
    } = this.parts;
    return !area && !exchange && !subscriber;
  }

  get shouldLabelFloat() {
    return this.focused || !this.empty;
  }

  @Input() set placeholder(value: string) {
    this._placeholder = value;
    this.stateChanges.next();
  }
  get placeholder(): string {
    return this._placeholder;
  }
  private _placeholder = '';

  @Input() set required(value: BooleanInput) {
    this._required = coerceBooleanProperty(value);
    this.stateChanges.next();
  }
  get required(): boolean {
    return this._required;
  }
  private _required = false;

  @Input() set disabled(value: BooleanInput) {
    this._disabled = coerceBooleanProperty(value);
    this._disabled ? this.parts.disable() : this.parts.enable();
    this.stateChanges.next();
  }
  get disabled(): boolean {
    return this._disabled;
  }
  private _disabled = false;

  @Input() set value(tel: MyTel | null) {
    const { area, exchange, subscriber } = tel || new MyTel('', '', '');
    this.parts.setValue({ area, exchange, subscriber });
    this.stateChanges.next();
  }
  get value(): MyTel | null {
    if (this.parts.valid) {
      const {
        value: { area, exchange, subscriber },
      } = this.parts;
      return new MyTel(area, exchange, subscriber);
    }
    return null;
  }

  private readonly _destroyed = new Subject<void>();

  onChange = (_: any) => {};
  onTouched = () => {};

  constructor(
    private readonly fb: FormBuilder,
    private readonly _focusMonitor: FocusMonitor,
    private readonly _elementRef: ElementRef<HTMLElement>,
    @Optional() @Self() readonly ngControl: NgControl | null,
  ) {
    this.parts = this.fb.group({
      area: [
        null,
        [Validators.required, Validators.minLength(3), Validators.maxLength(3)],
      ],
      exchange: [
        null,
        [Validators.required, Validators.minLength(3), Validators.maxLength(3)],
      ],
      subscriber: [
        null,
        [Validators.required, Validators.minLength(4), Validators.maxLength(4)],
      ],
    });

    if (this.ngControl != null) {
      this.ngControl.valueAccessor = this;
    }
  }

  setAriaLabel?(value: string): void {
    throw new Error('Method not implemented.');
  }

  get elementRef(): ElementRef {
    return this._elementRef;
  }

  ngAfterViewInit(): void {
    this._focusMonitor
      .monitor(this._elementRef, true)
      .pipe(takeUntil(this._destroyed))
      .subscribe((origin) => {
        if (this.focused && !origin) {
          this.onTouched();
        }
        this.focused = !!origin;
        this.stateChanges.next();
      });
  }

  ngOnDestroy(): void {
    this._destroyed.next();
    this._destroyed.complete();
    this.stateChanges.complete();
    this._focusMonitor.stopMonitoring(this._elementRef);
  }

  setDescribedByIds(ids: string[]) {
    this.describedBy = ids.join(' ');
  }

  onContainerClick(event: MouseEvent) {
    if ((event.target as Element).tagName.toLowerCase() !== 'input') {
      this._elementRef.nativeElement.querySelector('input')!.focus();
    }
  }

  writeValue(tel: MyTel | null): void {
    this.value = tel;
  }

  registerOnChange(fn: any): void {
    this.onChange = fn;
  }

  registerOnTouched(fn: any): void {
    this.onTouched = fn;
  }

  setDisabledState(isDisabled: boolean): void {
    this.disabled = isDisabled;
  }

  _handleInput(): void {
    this.onChange(this.value);
  }
}

