/**
 * This interface defines a single node of the trees data structure.
 */
export interface MyTreeNode extends NxTreeNode {
  children?: MyTreeNode[];
  label: string;
  icon?: string;
  query?: any;
}

/** Flat node with expandable and level information */
interface MyFlatTreeNode extends NxFlatTreeNode {
  icon: string;
  label: string;
  query?: any;
}

/**
 * @title Tree Example
 */
@Component({
  selector: 'tree-example',
  templateUrl: './tree-example.html',
  styleUrls: ['./tree-example.css'],
  imports: [
    NxTreeComponent,
    NxTreeNodeDefDirective,
    NxTreeNodeComponent,
    NxActionComponent,
    NxTreeNodeActionItem,
    NxTreeNodePaddingDirective,
    RouterLinkActive,
    RouterLink,
    NxIconComponent,
    NxActionIconDirective,
    NxTreeNodeToggleDirective,
  ],
})
export class TreeExampleComponent {
  navigationData: MyTreeNode[] = [
    {
      label: 'Option 1',
      icon: 'user-o',
      children: [
        {
          label: 'Option 1.1',
          query: { a: '1.1' },
        },
        {
          label: 'Option 1.2',
          children: [
            {
              label: 'Option 1.2.1',
              query: { a: '1.2.1' },
            },
            {
              label: 'Option 1.2.2',
              query: { a: '1.2.2' },
            },
            {
              label: 'Option 1.2.3',
              children: [
                {
                  label: 'Option 1.2.3.1',
                  children: [
                    {
                      label: 'Option 1.2.3.1.1',
                      query: { a: '1.2.3.1.1' },
                    },
                  ],
                },
              ],
            },
          ],
        },
        {
          label: 'Option 1.3',
          query: { a: '1.3' },
        },
      ],
    },
    {
      label: 'Option 2',
      icon: 'file',
      children: [
        {
          label: 'Option 2.1',
          query: { a: '2.1' },
        },
        {
          label: 'Option 2.2',
          query: { a: '2.2' },
        },
        {
          label: 'Option 2.3',
          query: { a: '2.3' },
        },
      ],
    },
    {
      label: 'Option 3',
      icon: 'file',
      query: { a: '3' },
    },
  ];

  _dataSource: NxTreeFlatDataSource<MyTreeNode, MyFlatTreeNode>;

  _treeControl: NxFlatTreeControl<MyFlatTreeNode>;

  constructor() {
    this._treeControl = new NxFlatTreeControl();
    this._dataSource = new NxTreeFlatDataSource(
      this._treeControl,
      this.navigationData,
    );
  }

  _hasChild = (_: number, node: NxFlatTreeNode) => node.expandable;
}

